// NOAA Heat Index Calculation in Arduino C++
float calcHeatIndex(float t, float h) {
  // Convert Celsius to Fahrenheit for Rothfusz formula
  float tf = (t * 1.8) + 32.0;
  float hiF = -42.379 + 2.04901523*tf + 10.14333127*h - 0.22475541*tf*h;
  return (hiF - 32.0) / 1.8; // Return in Celsius
}

