void regulateClimate(float t, float h) {
  // Cooling Fan with Hysteresis
  if (t >= 30.0) digitalWrite(PIN_FAN, HIGH);
  else if (t <= 26.0) digitalWrite(PIN_FAN, LOW);

  // Misting Atomizer with Hysteresis
  if (h <= 50.0) digitalWrite(PIN_MIST, HIGH);
  else if (h >= 70.0) digitalWrite(PIN_MIST, LOW);
}

